# Hypothesis: super() calls along the C3 MRO of a diamond reach Base in the expected order, and a property defined in one branch is accepted as a member.
from typing import reveal_type


class Base:
    def label(self) -> str:
        return "base"


class Left(Base):
    def label(self) -> str:
        return "left/" + super().label()


class Right(Base):
    @property
    def tag(self) -> str:
        return "right"

    def label(self) -> str:
        return "right/" + super().label()


class Bottom(Left, Right):
    def label(self) -> str:
        return "bottom/" + super().label()


node = Bottom()
reveal_type(node.label())
reveal_type(node.tag)
assert node.label() == "bottom/left/right/base"
assert node.tag == "right"
